// Add custom validation method for letters and spaces only
jQuery.validator.addMethod(
    "lettersSpacesOnly",
    function (value, element) {
        return this.optional(element) || /^[A-Za-z\s]+$/.test(value);
    },
    "Full Name must contain only letters and spaces."
);

jQuery(function () {
    $(".js-validation-user").validate({
        rules: {
            full_name: {
                required: true,
                lettersSpacesOnly: true,
                maxlength: 50,
            },
            email: { required: true, email: true, maxlength: 100 },
            password: { required: true, minlength: 8, maxlength: 8 },
            country_code: { required: true },
             phone_number: {
                required: true,
                minlength: 10,
                maxlength: 10,
                pattern: /^[6-9][0-9]{9}$/
            },
            "roles[]": { required: true },
        },
        messages: {
            full_name: {
                required: "Please enter full name.",
                lettersSpacesOnly:
                    "Full Name must contain only letters and spaces.",
                maxlength: "Full Name cannot exceed 50 characters.",
            },
            email: {
                required: "Please enter email.",
                email: "Please enter a valid email address.",
                maxlength: "Email cannot exceed 100 characters.",
            },
            password: {
                required: "Please enter password.",
                minlength: "Password cannot be less than 8 characters.",
                maxlength: "Password cannot exceed 8 characters.",
            },
            country_code: {
                required: "Please select country code.",
            },
            phone_number: {
                required: "Please enter phone number.",
                minlength: "Phone number must be exactly 10 digits.",
                maxlength: "Phone number must be exactly 10 digits.",
                pattern: "Phone number must start with 6, 7, 8, or 9.",
            },
            "roles[]": { required: "Please select at least one role." },
        },
        errorClass: "is-invalid",
        validClass: "is-valid",
        errorElement: "div",
        highlight: function (e) {
            $(e).addClass("is-invalid").removeClass("is-valid");
        },
        unhighlight: function (e) {
            $(e).addClass("is-valid").removeClass("is-invalid");
        },
        errorPlacement: function (e, t) {
            e.addClass("invalid-feedback");
            if (t.parent(".input-group").length) {
                t.parent().after(e);
            } else if (t.closest(".form-group").length) {
                t.closest(".form-group").append(e);
            } else if (t.closest(".mb-3").length) {
                t.closest(".mb-3").append(e);
            } else if (t.attr("name") === "roles[]") {
                t.closest(".mb-3").find(".form-check:last").after(e);
            } else {
                t.after(e);
            }
        },
        submitHandler: function (f) {
            f.submit();
        },
        invalidHandler: function (_, v) {
            if (v.errorList.length) {
                $(v.errorList[0].element).trigger("focus");
            }
        },
    });
});
